using System.Windows;using System.Windows.Controls;using System.Windows.Documents;using System.Windows.Media;
namespace BefundExplorer.App.Controls;
public sealed class MarkedTextBlock:TextBlock{public static readonly DependencyProperty MarkedTextProperty=DependencyProperty.Register(nameof(MarkedText),typeof(string),typeof(MarkedTextBlock),new PropertyMetadata(string.Empty,OnChanged));public string MarkedText{get=>(string)GetValue(MarkedTextProperty);set=>SetValue(MarkedTextProperty,value);}static void OnChanged(DependencyObject d,DependencyPropertyChangedEventArgs e)=>((MarkedTextBlock)d).Render();void Render(){Inlines.Clear();var text=MarkedText??"";int pos=0;while(pos<text.Length){int a=text.IndexOf('⟦',pos);if(a<0){Inlines.Add(new Run(text[pos..]));break;}if(a>pos)Inlines.Add(new Run(text[pos..a]));int b=text.IndexOf('⟧',a+1);if(b<0){Inlines.Add(new Run(text[a..]));break;}Inlines.Add(new Run(text[(a+1)..b]){FontWeight=FontWeights.SemiBold,Foreground=(Brush)Application.Current.FindResource("AccentBrush")});pos=b+1;}}}
